import{_ as t,o as e,c as l,a2 as o}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Настройка канала DingTalk","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/channels/dingtalk.md","filePath":"ru/integrations/channels/dingtalk.md","lastUpdated":1792323081000}'),n={name:"ru/integrations/channels/dingtalk.md"};function r(i,a,s,d,h,g){return e(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="настроика-канала-dingtalk" tabindex="-1">Настройка канала DingTalk <a class="header-anchor" href="#настроика-канала-dingtalk" aria-label="Permalink to &quot;Настройка канала DingTalk&quot;">​</a></h1><p>Подключите своего Bot в Memoh к DingTalk для личных и групповых чатов: входящие события приходят через режим DingTalk Stream, а ответы и медиа отправляются через официальные API DingTalk.</p><div class="warning custom-block"><p class="custom-block-title">Ограничения</p><ul><li>Ответы доставляются целыми сообщениями; потоковый вывод по токенам в DingTalk не поддерживается.</li></ul></div><h2 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h2><ul><li>Доступ к платформе разработчиков DingTalk вашей организации с правом создавать приложения.</li><li>Публичный URL обратного вызова не нужен: входящие события приходят по Stream-соединению DingTalk, которое Memoh поддерживает автоматически.</li></ul><h2 id="шаги" tabindex="-1">Шаги <a class="header-anchor" href="#шаги" aria-label="Permalink to &quot;Шаги&quot;">​</a></h2><h3 id="_1-создаите-приложение-dingtalk" tabindex="-1">1. Создайте приложение DingTalk <a class="header-anchor" href="#_1-создаите-приложение-dingtalk" aria-label="Permalink to &quot;1. Создайте приложение DingTalk&quot;">​</a></h3><p>На платформе разработчиков DingTalk вашей организации:</p><ol><li>Создайте или выберите приложение, которое будет выступать в роли Bot.</li><li>Включите для этого приложения возможность Bot / обмена сообщениями.</li><li>Скопируйте <strong>App Key</strong> и <strong>App Secret</strong>.</li><li>Выдайте приложению права на сообщения и опубликуйте его в организации, чтобы пользователи могли к нему обращаться.</li></ol><h3 id="_2-добавьте-канал-в-memoh" tabindex="-1">2. Добавьте канал в Memoh <a class="header-anchor" href="#_2-добавьте-канал-в-memoh" aria-label="Permalink to &quot;2. Добавьте канал в Memoh&quot;">​</a></h3><p>В Memoh:</p><ol><li>Откройте вкладку <strong>Platforms</strong> нужного Bot.</li><li>Нажмите <strong>Add Channel</strong> и выберите <strong>DingTalk</strong>.</li><li>Заполните <strong>App Key</strong> и <strong>App Secret</strong>.</li><li>Нажмите <strong>Save and Enable</strong>.</li></ol><p>Memoh поддерживает Stream-соединение с DingTalk автоматически — вставлять URL обратного вызова webhook никуда не нужно.</p><h2 id="учетные-данные" tabindex="-1">Учётные данные <a class="header-anchor" href="#учетные-данные" aria-label="Permalink to &quot;Учётные данные&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Поле</th><th>Обязательное</th><th>Описание</th></tr></thead><tbody><tr><td><strong>App Key</strong></td><td>Да</td><td>Ключ приложения DingTalk; копируется из учётных данных приложения на платформе разработчиков DingTalk.</td></tr><tr><td><strong>App Secret</strong></td><td>Да</td><td>Секрет приложения DingTalk; копируется там же.</td></tr></tbody></table><h2 id="проверка" tabindex="-1">Проверка <a class="header-anchor" href="#проверка" aria-label="Permalink to &quot;Проверка&quot;">​</a></h2><p>Отправьте Bot <code>/help</code> в личном чате или обратитесь к нему в групповом чате через @-упоминание с <code>/help</code>. Bot ответит списком команд — это подтверждает, что канал работает.</p><h2 id="групповые-чаты" tabindex="-1">Групповые чаты <a class="header-anchor" href="#групповые-чаты" aria-label="Permalink to &quot;Групповые чаты&quot;">​</a></h2><p>Bot работает в групповых чатах DingTalk: чтобы получить ответ, упомяните его через @ в поддерживаемой группе.</p><h2 id="отключение-и-смена-учетных-данных" tabindex="-1">Отключение и смена учётных данных <a class="header-anchor" href="#отключение-и-смена-учетных-данных" aria-label="Permalink to &quot;Отключение и смена учётных данных&quot;">​</a></h2><p>Отключить или удалить канал можно в любой момент на вкладке <strong>Platforms</strong> нужного Bot. Чтобы сменить учётные данные, обновите <strong>App Key</strong> / <strong>App Secret</strong> в той же панели и сохраните.</p>',21)])])}const k=t(n,[["render",r]]);export{p as __pageData,k as default};
